#!/usr/bin/env python3
"""Freeze the separately scoped resource review; never edits authored resources."""
import json,hashlib,sys
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'));from validate import question_hash,canonical_json
now=datetime.now(timezone.utc).isoformat();reviewer='robotics-contracts-independent-reviewer'
def load(p):return json.loads((ROOT/p).read_text())
def sha(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def write(p,x):
 f=ROOT/p
 if f.exists():raise RuntimeError('Refusing to overwrite frozen review: '+str(f))
 f.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
packet=load('audits/blind-learning-resources-v1.json');binding=load('audits/blind-binding-learning-resources-v1.json');data=load('data/learning-tools-course.json')['learningTools'];records={r['id']:r for a in data.values() for r in a};answers=load('audits/blind-answers-learning-resources-v1-contracts.json')
