findings=[
 {'id':'LR-P01','severity':'blocking','area':'stale numerical activation','targets':['app/learning-tools.js:registerBankNumericalFamilies','app/app.js:renderNumerical/renderVariant'],'finding':'Register an approved course family, remove that record from bank.learningTools.numericalFamilies, then register the new bank. The absent family remains in the module registry and listNumericalFamilies still labels it verified. The current state.variant renderer also trusts cached provenance.status and can display/save that old verified variant without rechecking current eligibility.','requiredRepair':'Evict every bank-registered family absent or ineligible in the current bank. Fail closed for generation/restoration/display of a cached course variant when its current family, content, question, source, policy or review binding is absent/stale. Keep historical attempts as historical, not current approvals. Add record-removal, bank-switch and cached-variant revocation tests.','evidence':'audits/learning-resources-v1-contracts-independent-checks.json: failClosedProbes; current renderVariant implementation inspected statically, not in a browser.'},
 {'id':'LR-P02','severity':'blocking','area':'context/source provenance loss','targets':['app/learning-resources.js:context','app/learning-resource-ui.js:contextPanel'],'finding':'The projection drops supplementalProvenance, externalEvidence, primaryImplementationEvidence, experimentProvenance and diagramSourceSlideIds. In the sampled canonical bank this is71 omissions across51 distinct questions. For example W07-L34-P1052-Q08 loses its exact notebook URL, SHA256 and cell8 binding; the remaining slide hyperlink does not replace that evidence.','requiredRepair':'Copy and render the relevant exact supplemental/implementation/experiment and diagram provenance with its original source qualifications, without inventing new source claims. Preserve full solution/premise context where necessary rather than only a generic source button. Test real notebook-derived and source-conflict fixtures as well as text-only questions.','evidence':'audits/learning-resources-v1-contracts-projection-checks.json: contextOmissions'},
 {'id':'LR-P03','severity':'blocking-defense-in-depth','area':'literal-answer and identity gate parity','targets':['app/learning-resources.js:eligibleQuestions/sameSet','scripts/learning_resources.py:tool_reasons'],'finding':'Under otherwise current synthetic test bindings, the JS projection accepts empty keys plus empty independent answers, nonexistent key IDs plus matching review IDs, duplicate independent IDs, and a whitespace-only reviewerId. The Python linked-question check likewise lacks valid-option membership and duplicate validation. The canonical bank validator normally rejects such malformed records, but the separate fail-closed resource gate must not convert them into projected approvals.','requiredRepair':'Require nonempty unique literal key and independent answer arrays containing only the question’s valid stable option IDs; require a nonblank independent reviewer identity; never substitute conditional intended IDs. Align JS/Python checks and test the rejected cases.','evidence':'audits/learning-resources-v1-contracts-independent-checks.json and additionalGateProbes in this summary'},
 {'id':'LR-P04','severity':'blocking-defense-in-depth','area':'source-page domain validation','targets':['app/learning-resources.js:eligibleQuestions/toolRecordAllowed','scripts/learning_resources.py:tool_reasons'],'finding':'The resource gates reject only unreviewed/unresolved dispositions, so an unknown disposition passes. A consistently mutated physicalPage0 also passes JS eligibility. The algorithm selector already uses a positive bounded physical-page check and an explicit disposition allowlist, but the projection/numerical gates do not.','requiredRepair':'Require one-based integer physicalPage within source.pageCount and an explicit supported disposition, with complete source/hash/sourceId/inspection consistency. Apply the same requirements to linked question citations as well as resource sourceRefs, in both language layers.','evidence':'audits/learning-resources-v1-contracts-independent-checks.json and additionalGateProbes in this summary'}
]
checks=['sourceSupport','assumptions','answerOrTrace','calculations','runtimeTests','explanation','sourceLinkage'];reviews=[]
for bind in binding['resourceBindings']:
 r=records[bind['id']];resp=[x for x in answers['responses'] if x['resourceId']==r['id']];tr=[x for x in answers['algorithmTraces'] if x['resourceId']==r['id']]
 reviews.append({'id':'contracts-learning-tool-v1-'+r['id'],'reviewerId':reviewer,'reviewedAt':now,'toolId':r['id'],'toolVersion':r['version'],'toolSha256':bind['sha256'],'decision':'verified','checks':dict.fromkeys(checks,True),'sourceVersions':{s['sourceId']:s['sourceSha256'] for s in r['sourceRefs']},'reviewedSlideIds':sorted({s['slideId'] for s in r['sourceRefs']}),'independentResponses':resp,'independentTraces':tr,'evidencePaths':['audits/blind-answers-learning-resources-v1-contracts.json','audits/learning-resources-v1-contracts-source-observations.json','audits/learning-resources-v1-contracts-independent-checks.json'],'blindAnswerSha256':sha('audits/blind-answers-learning-resources-v1-contracts.json'),'priorExposure':answers['priorExposure'],'scope':'This verifies the exact source-bound configuration and mathematical generator behavior, including examples, assumptions, complete traces/solutions and default Node/Python tests. It does not approve the separate extraction/activation policy, certify all source concepts, or claim browser layout/interaction testing. The flagged policy must keep course activation closed.','runtimeBoundary':'Default Python and Node only. Browser launch remains blocked before execution; no alternate route, installs, models, audio, NLTK or denied notebook retrieval.'})
